   doc.close()
   if out['ocr_pages']:out['method']='PDF + OCR' if out['ocr_pages']<out['pages'] else 'OCR toate paginile'
  elif ext in ['.jpg','.jpeg','.png','.tif','.tiff','.bmp','.webp']:
   im=Image.open(p);out['pages']=getattr(im,'n_frames',1);out['method']='OCR imagine'
   for i in range(out['pages']):
    im.seek(i);t,c=ocr(im.copy());texts.append('\\n[PAGINA '+str(i+1)+']\\n'+t);out['ocr_pages']+=1
    if len(re.findall('[A-Za-z]',t))<20:out['unreadable_pages'].append(i+1)
