   import openpyxl
   wb=openpyxl.load_workbook(p,read_only=True,data_only=False)
   for ws in wb:
    texts.append('FOAIE: '+ws.title)
    for row in ws.iter_rows(values_only=True):texts.append(' | '.join(str(v) for v in row if v is not None))
   wb.close();out['method']='Toate foile Excel'
