    try:t=b.decode('utf-8-sig')
    except UnicodeDecodeError:
     try:t=b.decode('utf-16') if b.startswith(b'\\xff\\xfe') else b.decode('cp1250')
     except Exception:t=b.decode('latin1',errors='replace')
    if '<html' in t.lower() or '<body' in t.lower():t=re.sub('<["'^>]+>'"',' ',t)
    texts.append(t);out['method']='Text integral'
  elif ext=='.xls':out['method']='Necesita citire Office';out['error']='Document binar Office: citire separata'
  elif ext in ['.zip','.rar','.7z']:out['method']='Arhiva; continut inventariat separat'
  elif ext=='.db':out['method']='Fisier tehnic';out['error']='Baza de date/cache; nu este document lizibil'
  else:out['method']='Format neacceptat';out['error']='Format fara cititor local'
  out['text']='\\n'.join(texts)
 except Exception as e:out['error']=str(e)
 out['text_sha']=hashlib.sha256(norm(out['text']).encode()).hexdigest() if out['text'] else ''
 return out
def run():
 rs=json.load(open(os.path.join(TMP,'all_files.json'),encoding='utf-8'));groups={}
 for r in rs:
  if 'sha256' in r and r['sha256'] not in groups:groups[r['sha256']]=r
 cache=os.path.join(TMP,'analysis.jsonl');done=set()
 if os.path.exists(cache):
  for l in open(cache,encoding='utf-8'):
   try:done.add(json.loads(l)['sha256'])
   except Exception:pass
 pending=[r for h,r in groups.items() if h not in done];start=time.time();n=0;pages=0;oc=0
 print('ANALIZA',len(pending),'continuturi unice',flush=True)
 with open(cache,'a',encoding='utf-8') as f:
  with concurrent.futures.ProcessPoolExecutor(max_workers=4) as pool:
   jobs={pool.submit(analyze,r):r for r in pending}
   for future in concurrent.futures.as_completed(jobs):
    r=jobs[future]
    try:a=future.result()
    except Exception as e:a={'sha256':r['sha256'],'path':r['path'],'text':'','error':str(e),'pages':0,'ocr_pages':0,'method':'Eroare citire','unreadable_pages':[]}
    f.write(json.dumps(a,ensure_ascii=False)+'\\n');f.flush();n+=1;pages+=a['pages'];oc+=a['ocr_pages']
    if n%20==0:print('CITIT',n,'/',len(pending),'pagini',pages,'OCR',oc,'sec',round(time.time()-start),flush=True)
 print('ANALIZA_FINALIZATA',n,'pagini',pages,'OCR',oc,flush=True)
